-- Continuous Recovery Audit
-- Select an approved installation role, a writable destination database, and a warehouse.
-- Run the complete file unchanged. Open OPEN_APP_URL in the final result.
-- Start with Small compute; Medium is optional for heavier work, not required for AI.
-- The selected database is the installation destination, not an account-wide access grant.
-- Discovery searches up to 20 role-visible databases; coverage reports skipped scopes.
-- AI needs the required USE AI FUNCTION privileges, a Cortex database role, and model access.
-- Warehouse work, AI calls and source packaging can incur charges. Existing approval gates remain.
-- No automatic privilege grants. Production actions and schedules require separate approval.
-- Optional settings are below; no edits are required. Full settings remain in readable source.
-- Readable implementation: EDIT_SOURCE_URL when available, or this solution's repository source.
-- Remove with this solution's TEARDOWN operation, not by dropping an unrelated schema.
EXECUTE IMMEDIATE $$
DECLARE
  options OBJECT DEFAULT PARSE_JSON(
-- BEGIN OPTIONAL CONFIGURATION
'{
  "destination_database": "",
  "destination_schema": "",
  "warehouse": "",
  "discovery_databases": [],
  "advanced": {}
}'
-- END OPTIONAL CONFIGURATION
  );
  phase_name VARCHAR DEFAULT 'Initialize settings';
  phase_query VARCHAR;
  result_rows RESULTSET;
  payload VARIANT;
  defaults OBJECT;
  aliases OBJECT;
  names ARRAY DEFAULT ARRAY_CONSTRUCT();
  values_sql ARRAY DEFAULT ARRAY_CONSTRUCT();
  invalid_config EXCEPTION (-20081, 'Invalid installer setting. Use the documented keys and matching scalar types.');
BEGIN
  -- ONESHOT INSTALLER FORMAT 1
  -- Generated payload: ordered SQL phases and original readable source; no external download.
  payload := PARSE_JSON(DECOMPRESS_STRING(TO_BINARY('', 'BASE64'), 'ZLIB'));
  defaults := payload:defaults::OBJECT;
  aliases := payload:aliases::OBJECT;
  LET requested RESULTSET := (SELECT KEY, VALUE FROM TABLE(FLATTEN(INPUT => :options)) WHERE KEY <> 'advanced');
  FOR requested_option IN requested DO
    LET setting_name VARCHAR := GET(:aliases, requested_option.KEY)::VARCHAR;
    LET setting_value VARIANT := requested_option.VALUE;
    IF (:setting_name IS NULL) THEN RAISE invalid_config; END IF;
    IF (IS_ARRAY(:setting_value)) THEN
      setting_value := TO_JSON(:setting_value)::VARIANT;
    END IF;
    IF (:setting_value::VARCHAR NOT IN ('', '[]')) THEN
      defaults := OBJECT_INSERT(:defaults, :setting_name, :setting_value, TRUE);
    END IF;
  END FOR;
  IF (NOT IS_OBJECT(options:advanced)) THEN RAISE invalid_config; END IF;
  LET advanced_options RESULTSET := (SELECT KEY, VALUE FROM TABLE(FLATTEN(INPUT => :options:advanced)));
  FOR advanced_option IN advanced_options DO
    IF (NOT ARRAY_CONTAINS(advanced_option.KEY::VARIANT, OBJECT_KEYS(:defaults))) THEN RAISE invalid_config; END IF;
    LET previous_value VARIANT := GET(:defaults, advanced_option.KEY);
    IF (TYPEOF(:previous_value) <> TYPEOF(advanced_option.VALUE)
        AND NOT (IS_DECIMAL(:previous_value) AND IS_DECIMAL(advanced_option.VALUE))) THEN RAISE invalid_config; END IF;
    defaults := OBJECT_INSERT(:defaults, advanced_option.KEY, advanced_option.VALUE, TRUE);
  END FOR;
  LET settings_rows RESULTSET := (SELECT KEY, VALUE FROM TABLE(FLATTEN(INPUT => :defaults)) ORDER BY KEY);
  FOR setting_row IN settings_rows DO
    IF (NOT REGEXP_LIKE(setting_row.KEY, '[A-Z_][A-Z0-9_]*')) THEN RAISE invalid_config; END IF;
    names := ARRAY_APPEND(:names, setting_row.KEY);
    LET setting_sql VARCHAR := CASE
      WHEN IS_NULL_VALUE(setting_row.VALUE) THEN 'NULL'
      WHEN IS_VARCHAR(setting_row.VALUE) THEN CHR(39) || REPLACE(REPLACE(setting_row.VALUE::VARCHAR, CHR(92), CHR(92)||CHR(92)), CHR(39), CHR(39)||CHR(39)) || CHR(39)
      ELSE setting_row.VALUE::VARCHAR END;
    values_sql := ARRAY_APPEND(:values_sql, :setting_sql);
  END FOR;
  EXECUTE IMMEDIATE 'SET (' || ARRAY_TO_STRING(:names, ',') || ') = (' || ARRAY_TO_STRING(:values_sql, ',') || ')';
  LET phase_index INTEGER := 0;
  WHILE (:phase_index < ARRAY_SIZE(:payload:phases)) DO
    LET current_phase VARIANT := GET(:payload:phases, :phase_index);
    phase_name := current_phase:name::VARCHAR;
    LET phase_sql VARCHAR := SUBSTR(:payload:source::VARCHAR, current_phase:offset::INTEGER, current_phase:length::INTEGER);
    IF (current_phase:completion::BOOLEAN) THEN
      phase_sql := REPLACE(:phase_sql, 'prior_query VARCHAR DEFAULT LAST_QUERY_ID()', 'prior_query VARCHAR DEFAULT GETVARIABLE(''ONESHOT_PREVIOUS_PHASE_QUERY'')');
    END IF;
    IF (:phase_index = ARRAY_SIZE(:payload:phases) - 1 AND :phase_query IS NOT NULL) THEN
      EXECUTE IMMEDIATE 'SET ONESHOT_PREVIOUS_PHASE_QUERY = ' || CHR(39) || :phase_query || CHR(39);
    END IF;
    result_rows := (EXECUTE IMMEDIATE :phase_sql);
    phase_query := SQLID;
    phase_index := :phase_index + 1;
  END WHILE;
  RETURN TABLE(result_rows);
EXCEPTION
  WHEN OTHER THEN
    LET failure VARCHAR := SQLERRM;
    LET failure_code INTEGER := SQLCODE;
    result_rows := (SELECT 'INSTALLATION_FAILED' AS STATUS, NULL::VARCHAR AS OPEN_APP_URL,
      :phase_name AS FAILED_PHASE, :failure AS ERROR, :failure_code AS ERROR_CODE,
      :phase_query AS PREVIOUS_PHASE_QUERY_ID,
      'Resolve the reported error before rerunning. Previously created objects may remain; use the installation teardown when available.' AS NEXT_ACTION);
    RETURN TABLE(result_rows);
END;
$$;
